async () => {
  const julyPath = "/private/var/folders/c7/vw1b0dhs3dddrx6r102srgvm0000gn/T/t5-round3-TuTFMp/GPAO-T5/2026-07 정산";
  const augPath = "/private/var/folders/c7/vw1b0dhs3dddrx6r102srgvm0000gn/T/t5-round3-TuTFMp/GPAO-T5/2026-08 정산";

  const julySalesFile = await t5.call("local_file", { action: "read", path: `${julyPath}/2026-07 매출정산.csv`});
  const julySummaryFile = await t5.call("local_file", { action: "read", path: `${julyPath}/7월 정산내역.csv`});
  const augSalesFile = await t5.call("local_file", { action: "read", path: `${augPath}/2026-08 매출정산.csv`});
  const augSummaryFile = await t5.call("local_file", { action: "read", path: `${augPath}/8월 정산내역.csv`});

  function parseCsv(text) {
    const lines = text.trim().split(/\r?\n/);
    const header = lines[0].split(",").map(h => h.trim());
    const rows = lines.slice(1).map(line => {
      const cols = line.split(",");
      const obj = {};
      header.forEach((h, i) => { obj[h] = (cols[i] || "").trim(); });
      return obj;
    });
    return { header, rows };
  }

  const julySales = parseCsv(julySalesFile.result.text);
  const augSales = parseCsv(augSalesFile.result.text);

  function sumColumn(rows, colName) {
    return rows.reduce((sum, r) => sum + (parseFloat(r[colName].replace(/,/g, "")) || 0), 0);
  }

  const julyTotalSales = sumColumn(julySales.rows, "매출합계");
  const augTotalSales = sumColumn(augSales.rows, "매출합계");

  const julyCount = julySales.rows.length;
  const augCount = augSales.rows.length;

  const salesDiff = augTotalSales - julyTotalSales;
  const salesRate = julyTotalSales ? (salesDiff / julyTotalSales * 100) : 0;

  // 간단 요약 텍스트 생성 (한국어)
  const summaryLines = [];
  summaryLines.push("[7월 vs 8월 정산 비교 요약]");
  summaryLines.push("");
  summaryLines.push(`1) 전체 매출 합계\n - 7월: ${julyTotalSales.toLocaleString()}원\n - 8월: ${augTotalSales.toLocaleString()}원\n - 증감: ${salesDiff >= 0 ? "+" : ""}${salesDiff.toLocaleString()}원 (${salesRate.toFixed(1)}%)`);
  summaryLines.push("");
  summaryLines.push(`2) 거래 건수\n - 7월: ${julyCount}건\n - 8월: ${augCount}건\n - 증감: ${(augCount - julyCount) >= 0 ? "+" : ""}${augCount - julyCount}건`);
  summaryLines.push("");
  summaryLines.push("※ 상세 항목별 비교는 각 월 정산내역.csv를 참고하세요.");

  const summaryText = summaryLines.join("\n");

  // 바탕화면에 저장
  const desktopPath = "~/Desktop/7월_8월_정산_비교요약.txt";
  const written = await t5.call("local_file", { action: "write", path: desktopPath, text: summaryText, source: julyPath });

  console.log({
    ok: true,
    summary: "7월·8월 매출 정산 비교 요약을 바탕화면에 저장했습니다.",
    result: {
      desktopFile: written.result.path,
      julyTotalSales,
      augTotalSales,
      julyCount,
      augCount,
      salesDiff,
      salesRate
    }
  });
}

